package com.lifeos.tasks; import com.lifeos.tasks.dto.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/tasks") public class TaskController {private final TaskService service; public TaskController(TaskService service){this.service=service;} @GetMapping public List<TaskResponse> list(@AuthenticationPrincipal UserDetails p){return service.list(p.getUsername());} @GetMapping("/{id}") public TaskResponse get(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){return service.get(id,p.getUsername());} @PostMapping @ResponseStatus(HttpStatus.CREATED) public TaskResponse create(@Valid @RequestBody TaskRequest r,@AuthenticationPrincipal UserDetails p){return service.create(r,p.getUsername());} @PutMapping("/{id}") public TaskResponse update(@PathVariable Long id,@Valid @RequestBody TaskRequest r,@AuthenticationPrincipal UserDetails p){return service.update(id,r,p.getUsername());} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){service.delete(id,p.getUsername());}}
